export const ARMOUR_SLOT_IDS = ["HEAD", "BODY", "GLOVES", "BOOTS"] as const;
export const WEAPON_SLOT_IDS = ["MAIN_LEFT", "MAIN_RIGHT"] as const;

export type ArmourSlotId = (typeof ARMOUR_SLOT_IDS)[number];
export type WeaponSlotId = (typeof WEAPON_SLOT_IDS)[number];
export type PaperDollSlotId = ArmourSlotId | WeaponSlotId;
export type PaperDollSyncResult = "synchronized" | "unchanged" | "unavailable";
export type WfrpArmourLocation = "head" | "lArm" | "rArm" | "lLeg" | "rLeg" | "body";
export type WfrpHand = "l" | "r";

export interface EquipmentSnapshot {
  equipped: boolean;
  id: string;
  name: string;
  type: "armour" | "weapon";
  uuid: string;
  armourPoints?: Record<WfrpArmourLocation, number>;
  offhand?: boolean;
  twoHanded?: boolean;
}

export interface PaperDollSlotAssignment {
  slotId: PaperDollSlotId;
  uuid: string;
}

export interface PaperDollSlotAddress {
  slotId: string;
  slotIndex: number;
}

export interface PaperDollSlotChange extends PaperDollSlotAddress {
  from: string | null;
  to: string | null;
}

export type PaperDollSlotState = Record<string, Record<string, string | null | undefined>>;
