import { equipFromPaperDoll, isItemAllowedInPaperDollSlot } from "./wfrp-equipment";
import { reportPaperDollError } from "./report-paper-doll-error";
import { syncActor } from "./synchronize-paper-doll";
import { isRecord, isWfrpActor, isWfrpOwnedItem } from "./wfrp-runtime-types";
import type { PaperDollSlotAddress } from "../../../types/patches/paper-doll/Equipment";

const PATCH_MARKER = Symbol.for("paper-doll-wfrp4e.equipped-state");

type PaperDollEquip = (
  this: { actor?: unknown },
  uuid: string,
  equipped: boolean,
  slotData: unknown,
) => Promise<void>;

type PaperDollPrototype = Record<PropertyKey, unknown>;

interface FromUuidResolver {
  fromUuid?: (uuid: string) => Promise<unknown>;
  ui?: {
    paperDoll?: {
      prototype?: PaperDollPrototype;
    };
  };
}

function getPaperDollPrototype(): PaperDollPrototype | null {
  const paperDoll = (globalThis as FromUuidResolver).ui?.paperDoll;

  return paperDoll?.prototype ?? null;
}

function assertPaperDollEquipApi(
  prototype: PaperDollPrototype | null,
  currentEquip: unknown,
  fromUuid: unknown,
): asserts prototype is PaperDollPrototype {
  if (!prototype || typeof currentEquip !== "function" || typeof fromUuid !== "function") {
    throw new Error("Paper Doll's required equip integration API is unavailable.");
  }
}

function getSlotAddress(value: unknown): PaperDollSlotAddress | null {
  if (!isRecord(value) || typeof value["slotId"] !== "string") {
    return null;
  }

  const slotIndex = Number(value["slotIndex"]);

  return Number.isInteger(slotIndex) ? { slotId: value["slotId"], slotIndex } : null;
}

/**
 * Paper Doll calls equip(false) before it writes the actor slot flag. The
 * actor-update hook performs the actual WFRP unequip after that flag change,
 * which keeps lower armour layers equipped until the visible layer is removed.
 */
function deferUnequipToActorSlotChange(): Promise<void> {
  return Promise.resolve();
}

/**
 * Paper Doll's optional equipped-path setting would otherwise also write an
 * item's equipped state. For WFRP4e, the compatibility hooks own those
 * updates so armour can remain equipped underneath a newly added layer.
 */
export function enforcePaperDollEquippedState(): void {
  const prototype = getPaperDollPrototype();
  const currentEquip = prototype?.["equip"];
  const fromUuid = (globalThis as FromUuidResolver).fromUuid;

  assertPaperDollEquipApi(prototype, currentEquip, fromUuid);

  // The ready hook can run again during a Foundry lifecycle refresh. The
  // marker is set only after this exact wrapper has been installed.
  if (prototype[PATCH_MARKER] === true) {
    return;
  }

  const originalEquip = currentEquip as PaperDollEquip;

  prototype["equip"] = async function equip(
    this: { actor?: unknown },
    uuid: string,
    equipped: boolean,
    slotData: unknown,
  ): Promise<void> {
    const item = await fromUuid(uuid);

    if (!isWfrpOwnedItem(item)) {
      return originalEquip.call(this, uuid, equipped, slotData);
    }

    const slotAddress = getSlotAddress(slotData);

    if (!equipped) {
      return deferUnequipToActorSlotChange();
    }

    if (!isWfrpActor(this.actor)) {
      throw new Error(`Paper Doll did not provide a WFRP actor while equipping ${item.uuid}.`);
    }

    if (!slotAddress) {
      throw new Error(`Paper Doll did not provide a valid slot while equipping ${item.uuid}.`);
    }

    if (!isItemAllowedInPaperDollSlot(item, slotAddress.slotId)) {
      throw new Error(
        `Paper Doll attempted to equip ${item.uuid} in incompatible ${slotAddress.slotId} slot.`,
      );
    }

    try {
      await equipFromPaperDoll(this.actor, item, slotAddress);
    } catch (error) {
      reportPaperDollError(`could not equip ${item.name} from Paper Doll`, error);

      try {
        await syncActor(this.actor);
      } catch (syncError) {
        reportPaperDollError(`could not restore ${item.name}'s Paper Doll slot`, syncError);
      }

      throw error;
    }
  };
  prototype[PATCH_MARKER] = true;
}
