import { deriveEquipmentSlots } from "../../../functions/patches/paper-doll/derive-equipment-slots";
import { isPaperDollSlotState } from "../../../functions/patches/paper-doll/is-paper-doll-slot-state";
import {
  ARMOUR_SLOT_IDS,
  WEAPON_SLOT_IDS,
  type PaperDollSyncResult,
  type PaperDollSlotAssignment,
  type PaperDollSlotState,
} from "../../../types/patches/paper-doll/Equipment";
import { getActorMainHand, getEquipmentSnapshot, getItemEquippedState } from "./wfrp-equipment";
import { isRecord, isWfrpActor, type WfrpActor, type WfrpOwnedItem } from "./wfrp-runtime-types";
import { runPaperDollTask } from "./report-paper-doll-error";

export const PAPER_DOLL_MODULE_ID = "fvtt-paper-doll-ui";
export const PAPER_DOLL_SLOT_FLAG = "slots";

const syncInProgress = new Map<string, Promise<PaperDollSyncResult>>();
const queuedActorUuids = new Set<string>();

function cloneSlotState(state: PaperDollSlotState): PaperDollSlotState {
  return Object.fromEntries(
    Object.entries(state).map(([slotId, entries]) => [slotId, { ...entries }]),
  );
}

function getSlotState(actor: WfrpActor): PaperDollSlotState {
  const slots = actor.getFlag(PAPER_DOLL_MODULE_ID, PAPER_DOLL_SLOT_FLAG);

  if (slots === undefined) {
    return {};
  }

  if (!isPaperDollSlotState(slots)) {
    throw new Error("Paper Doll's existing slot flag has an invalid shape.");
  }

  return cloneSlotState(slots);
}

function getConfiguredSlotIds(): Set<string> {
  const globalConfig = game?.settings.get(PAPER_DOLL_MODULE_ID, "globalConfig");

  if (!isRecord(globalConfig) || !isRecord(globalConfig["SLOTS"])) {
    return new Set([...ARMOUR_SLOT_IDS, ...WEAPON_SLOT_IDS]);
  }

  const configuredSlotIds = new Set(
    Object.values(globalConfig["SLOTS"])
      .filter(isRecord)
      .flatMap((column) => Object.keys(column)),
  );

  // Paper Doll merges an empty persisted setting with its default layout at
  // runtime. Fall back to the standard slots when only that empty raw value is
  // available through Foundry's settings API.
  return configuredSlotIds.size
    ? configuredSlotIds
    : new Set([...ARMOUR_SLOT_IDS, ...WEAPON_SLOT_IDS]);
}

function hasSameSlotState(a: PaperDollSlotState, b: PaperDollSlotState): boolean {
  return JSON.stringify(a) === JSON.stringify(b);
}

function applyAssignments(
  current: PaperDollSlotState,
  assignments: readonly PaperDollSlotAssignment[],
  equipmentItemUuids: ReadonlySet<string>,
  configuredSlotIds: ReadonlySet<string>,
): PaperDollSlotState {
  const next = cloneSlotState(current);
  const assignmentBySlot = new Map(
    assignments.map((assignment) => [assignment.slotId, assignment.uuid]),
  );

  for (const slotId of [...ARMOUR_SLOT_IDS, ...WEAPON_SLOT_IDS]) {
    if (!configuredSlotIds.has(slotId)) {
      continue;
    }

    const currentValue = next[slotId]?.["0"] ?? null;
    const assignment = assignmentBySlot.get(slotId) ?? null;

    if (assignment) {
      next[slotId] ??= {};
      next[slotId]["0"] = assignment;
    } else if (currentValue && equipmentItemUuids.has(currentValue)) {
      next[slotId] ??= {};
      next[slotId]["0"] = null;
    }
  }

  return next;
}

function clearUnequippedStatefulItems(
  state: PaperDollSlotState,
  items: readonly WfrpOwnedItem[],
  equipmentItemUuids: ReadonlySet<string>,
): PaperDollSlotState {
  const itemByUuid = new Map(items.map((item) => [item.uuid, item]));
  const next = cloneSlotState(state);

  for (const entries of Object.values(next)) {
    for (const [slotIndex, itemUuid] of Object.entries(entries)) {
      if (!itemUuid || equipmentItemUuids.has(itemUuid)) {
        continue;
      }

      const item = itemByUuid.get(itemUuid);

      if (item && getItemEquippedState(item) === false) {
        entries[slotIndex] = null;
      }
    }
  }

  return next;
}

export function isSynchronizingActor(actor: WfrpActor): boolean {
  return syncInProgress.has(actor.uuid);
}

function assertWfrpSyncActor(actor: unknown): asserts actor is WfrpActor {
  if (!isWfrpActor(actor)) {
    throw new Error("Paper Doll synchronization requires a WFRP actor document.");
  }
}

function assertWfrpSystem(): void {
  if (!game || game.system.id !== "wfrp4e") {
    throw new Error("Paper Doll synchronization is only available in a WFRP4e world.");
  }
}

async function synchronizeActor(actor: WfrpActor): Promise<PaperDollSyncResult> {
  const current = getSlotState(actor);
  const items = Array.from(actor.items);
  const snapshots = items
    .map(getEquipmentSnapshot)
    .filter((snapshot): snapshot is NonNullable<typeof snapshot> => snapshot !== null);
  const equipmentItemUuids = new Set(snapshots.map((snapshot) => snapshot.uuid));
  const next = clearUnequippedStatefulItems(
    applyAssignments(
      current,
      deriveEquipmentSlots(snapshots, getActorMainHand(actor)),
      equipmentItemUuids,
      getConfiguredSlotIds(),
    ),
    items,
    equipmentItemUuids,
  );

  if (hasSameSlotState(current, next)) {
    return "unchanged";
  }

  await actor.setFlag(PAPER_DOLL_MODULE_ID, PAPER_DOLL_SLOT_FLAG, next);
  return "synchronized";
}

export async function syncActor(actorValue: unknown): Promise<PaperDollSyncResult> {
  assertWfrpSyncActor(actorValue);
  assertWfrpSystem();

  const actor = actorValue;

  if (game.modules.get(PAPER_DOLL_MODULE_ID)?.active !== true) {
    return "unavailable";
  }

  const pendingSynchronization = syncInProgress.get(actor.uuid);

  if (pendingSynchronization) {
    await pendingSynchronization;
    return syncActor(actor);
  }

  const synchronization = synchronizeActor(actor).finally(() => {
    if (syncInProgress.get(actor.uuid) === synchronization) {
      syncInProgress.delete(actor.uuid);
    }
  });
  syncInProgress.set(actor.uuid, synchronization);

  return synchronization;
}

export function scheduleActorSync(actor: WfrpActor): void {
  if (queuedActorUuids.has(actor.uuid)) {
    return;
  }

  queuedActorUuids.add(actor.uuid);
  queueMicrotask(() => {
    queuedActorUuids.delete(actor.uuid);
    runPaperDollTask(syncActor(actor), `could not synchronize equipped items for ${actor.uuid}`);
  });
}

export async function syncAllActors(): Promise<PaperDollSyncResult[]> {
  assertWfrpSystem();

  return Promise.all(Array.from(game.actors, (actor) => syncActor(actor)));
}
