import type {
  EquipmentSnapshot,
  PaperDollSlotAddress,
  WfrpArmourLocation,
  WfrpHand,
} from "../../../types/patches/paper-doll/Equipment";
import { isRecord, type WfrpActor, type WfrpOwnedItem } from "./wfrp-runtime-types";

const ARMOUR_LOCATIONS: readonly WfrpArmourLocation[] = [
  "head",
  "lArm",
  "rArm",
  "lLeg",
  "rLeg",
  "body",
];

function getSystemRecord(item: WfrpOwnedItem): Record<string, unknown> {
  if (!isRecord(item.system)) {
    throw new Error(`WFRP item ${item.uuid} has no usable system data.`);
  }

  return item.system;
}

function getBooleanField(item: WfrpOwnedItem, field: string): boolean | null {
  const value = getSystemRecord(item)[field];

  if (value === undefined) {
    return null;
  }

  if (!isRecord(value) || typeof value["value"] !== "boolean") {
    throw new Error(`WFRP item ${item.uuid} has an invalid ${field} field.`);
  }

  return value["value"];
}

function getRequiredBooleanField(item: WfrpOwnedItem, field: string): boolean {
  const value = getBooleanField(item, field);

  if (value === null) {
    throw new Error(`WFRP item ${item.uuid} is missing its ${field} field.`);
  }

  return value;
}

export function getItemEquippedState(item: WfrpOwnedItem): boolean | null {
  return getBooleanField(item, "equipped");
}

export function hasEquippedState(item: WfrpOwnedItem): boolean {
  return getItemEquippedState(item) !== null;
}

function getArmourPoints(item: WfrpOwnedItem): Record<WfrpArmourLocation, number> {
  const points = getSystemRecord(item)["AP"];

  if (!isRecord(points)) {
    throw new Error(`WFRP armour ${item.uuid} has no usable AP data.`);
  }

  return Object.fromEntries(
    ARMOUR_LOCATIONS.map((location) => {
      const value = points[location];

      if (typeof value !== "number" || !Number.isFinite(value)) {
        throw new Error(`WFRP armour ${item.uuid} has an invalid AP.${location} value.`);
      }

      return [location, value];
    }),
  ) as Record<WfrpArmourLocation, number>;
}

export function getActorMainHand(actor: WfrpActor): WfrpHand {
  if (!isRecord(actor.system) || !isRecord(actor.system["details"])) {
    throw new Error(`WFRP actor ${actor.uuid} has no usable details data.`);
  }

  const mainHand = actor.system["details"]["mainHand"];

  if (mainHand !== "l" && mainHand !== "r") {
    throw new Error(`WFRP actor ${actor.uuid} has an invalid details.mainHand value.`);
  }

  return mainHand;
}

export function getEquipmentSnapshot(item: WfrpOwnedItem): EquipmentSnapshot | null {
  if (item.type !== "armour" && item.type !== "weapon") {
    return null;
  }

  const snapshot: EquipmentSnapshot = {
    equipped: getRequiredBooleanField(item, "equipped"),
    id: item.id,
    name: item.name,
    type: item.type,
    uuid: item.uuid,
  };

  if (item.type === "armour") {
    snapshot.armourPoints = getArmourPoints(item);
  } else {
    snapshot.offhand = getRequiredBooleanField(item, "offhand");
    snapshot.twoHanded = getRequiredBooleanField(item, "twohanded");
  }

  return snapshot;
}

function isArmourAllowedInSlot(item: WfrpOwnedItem, slotId: string): boolean {
  if (item.type !== "armour") {
    return false;
  }

  const armourPoints = getArmourPoints(item);

  switch (slotId) {
    case "HEAD":
      return armourPoints.head > 0;
    case "BODY":
      return armourPoints.body > 0;
    case "GLOVES":
      return armourPoints.lArm > 0 || armourPoints.rArm > 0;
    case "BOOTS":
      return armourPoints.lLeg > 0 || armourPoints.rLeg > 0;
    default:
      return false;
  }
}

/**
 * Keep WFRP4e's physical equipment slots type-safe while allowing the
 * presentation slots to hold any non-weapon, non-armour item.
 */
export function isItemAllowedInPaperDollSlot(item: WfrpOwnedItem, slotId: string): boolean {
  if (slotId === "MAIN_LEFT" || slotId === "MAIN_RIGHT") {
    return item.type === "weapon";
  }

  if (slotId === "HEAD" || slotId === "BODY" || slotId === "GLOVES" || slotId === "BOOTS") {
    return isArmourAllowedInSlot(item, slotId);
  }

  return item.type !== "weapon" && item.type !== "armour";
}

function getPhysicalHand(slotData: PaperDollSlotAddress): WfrpHand | null {
  if (slotData.slotId === "MAIN_LEFT") {
    return "l";
  }

  if (slotData.slotId === "MAIN_RIGHT") {
    return "r";
  }

  return null;
}

export async function equipFromPaperDoll(
  actor: WfrpActor,
  item: WfrpOwnedItem,
  slotData: PaperDollSlotAddress,
): Promise<void> {
  const equipped = getItemEquippedState(item);

  if (equipped === null) {
    return;
  }

  const snapshot = getEquipmentSnapshot(item);
  const changes: Record<string, unknown> = {};
  let desiredOffhand: boolean | undefined;

  if (snapshot?.type === "weapon") {
    const physicalHand = getPhysicalHand(slotData);

    if (snapshot.twoHanded) {
      desiredOffhand = false;
    } else if (physicalHand) {
      desiredOffhand = physicalHand !== getActorMainHand(actor);
    }
  }

  if (!equipped) {
    changes["system.equipped.value"] = true;
  }

  if (desiredOffhand !== undefined && snapshot?.offhand !== desiredOffhand) {
    changes["system.offhand.value"] = desiredOffhand;
  }

  if (Object.keys(changes).length) {
    await item.update(changes);
  }
}

export async function unequipFromPaperDoll(item: WfrpOwnedItem): Promise<void> {
  if (getItemEquippedState(item) !== true) {
    return;
  }

  await item.update({ "system.equipped.value": false });
}
