import type { PaperDollSlotState } from "../../../types/patches/paper-doll/Equipment";

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isSlotIndex(value: string): boolean {
  return /^(0|[1-9]\d*)$/.test(value);
}

function isSlotItemUuid(value: unknown): value is string | null | undefined {
  return value === null || value === undefined || (typeof value === "string" && value.length > 0);
}

/** Validate Paper Doll's persisted slot flag before reading or modifying it. */
export function isPaperDollSlotState(value: unknown): value is PaperDollSlotState {
  return (
    isRecord(value) &&
    Object.entries(value).every(
      ([slotId, entries]) =>
        slotId.length > 0 &&
        isRecord(entries) &&
        Object.entries(entries).every(
          ([slotIndex, itemUuid]) => isSlotIndex(slotIndex) && isSlotItemUuid(itemUuid),
        ),
    )
  );
}
