import { findSlotChanges } from "../../../functions/patches/paper-doll/find-slot-changes";
import { isPaperDollSlotState } from "../../../functions/patches/paper-doll/is-paper-doll-slot-state";
import type {
  PaperDollSlotAddress,
  PaperDollSlotState,
} from "../../../types/patches/paper-doll/Equipment";
import {
  equipFromPaperDoll,
  hasEquippedState,
  isItemAllowedInPaperDollSlot,
  unequipFromPaperDoll,
} from "./wfrp-equipment";
import { enforcePaperDollEquippedState } from "./enforce-paper-doll-equipped-state";
import { enforcePaperDollSlotTypes } from "./enforce-paper-doll-slot-types";
import { registerPaperDollSlotTooltips } from "./register-slot-tooltips";
import { reportPaperDollError, runPaperDollTask } from "./report-paper-doll-error";
import { isRecord, isWfrpActor, isWfrpOwnedItem, type WfrpActor } from "./wfrp-runtime-types";
import {
  isSynchronizingActor,
  PAPER_DOLL_MODULE_ID,
  PAPER_DOLL_SLOT_FLAG,
  scheduleActorSync,
  syncAllActors,
} from "./synchronize-paper-doll";

const pendingUnequips = new Map<string, Set<string>>();

type UpdatedSlotState =
  | { kind: "absent" }
  | { kind: "malformed"; reason: string }
  | { kind: "valid"; state: PaperDollSlotState };

function isPaperDollEnabled(): boolean {
  return game?.system.id === "wfrp4e" && game.modules.get(PAPER_DOLL_MODULE_ID)?.active === true;
}

function getUpdatedSlotState(changes: unknown): UpdatedSlotState {
  if (!isRecord(changes)) {
    return { kind: "absent" };
  }

  if (!("flags" in changes)) {
    return { kind: "absent" };
  }

  const flags = changes["flags"];

  if (!isRecord(flags)) {
    return { kind: "malformed", reason: "the flags update is not an object" };
  }

  if (!(PAPER_DOLL_MODULE_ID in flags)) {
    return { kind: "absent" };
  }

  const paperDollFlags = flags[PAPER_DOLL_MODULE_ID];

  if (!isRecord(paperDollFlags)) {
    return { kind: "malformed", reason: "the Paper Doll flag update is not an object" };
  }

  if (!(PAPER_DOLL_SLOT_FLAG in paperDollFlags)) {
    return { kind: "absent" };
  }

  if (!isPaperDollSlotState(paperDollFlags[PAPER_DOLL_SLOT_FLAG])) {
    return { kind: "malformed", reason: "the Paper Doll slots update has an invalid shape" };
  }

  return { kind: "valid", state: paperDollFlags[PAPER_DOLL_SLOT_FLAG] };
}

function requireUpdatedSlotState(changes: unknown): PaperDollSlotState | null {
  const result = getUpdatedSlotState(changes);

  if (result.kind === "malformed") {
    throw new Error(`Paper Doll slot update cannot be synchronized: ${result.reason}.`);
  }

  return result.kind === "valid" ? result.state : null;
}

function getOwnedItem(actor: WfrpActor, uuid: string) {
  return Array.from(actor.items).find((item) => item.uuid === uuid) ?? null;
}

function queueUnequip(actor: WfrpActor, uuid: string): void {
  const itemUuids = pendingUnequips.get(actor.uuid) ?? new Set<string>();
  itemUuids.add(uuid);
  pendingUnequips.set(actor.uuid, itemUuids);
}

function getSlotAddress(value: unknown): PaperDollSlotAddress | null {
  if (!isRecord(value) || typeof value["slotId"] !== "string") {
    return null;
  }

  const slotIndex = Number(value["slotIndex"]);

  if (!Number.isInteger(slotIndex)) {
    return null;
  }

  return {
    slotId: value["slotId"],
    slotIndex,
  };
}

function handlePaperDollSwap(
  actorValue: unknown,
  targetValue: unknown,
  originValue: unknown,
): void {
  if (!isPaperDollEnabled() || !isWfrpActor(actorValue)) {
    return;
  }

  for (const value of [targetValue, originValue]) {
    if (!isRecord(value) || typeof value["item"] !== "string") {
      continue;
    }

    const slotData = getSlotAddress(value);
    const item = slotData ? getOwnedItem(actorValue, value["item"]) : null;

    if (item && slotData && isItemAllowedInPaperDollSlot(item, slotData.slotId)) {
      runPaperDollTask(
        equipFromPaperDoll(actorValue, item, slotData),
        `could not equip ${item.name} after a Paper Doll slot swap`,
      );
    }
  }
}

function handlePreUpdateActor(actorValue: unknown, changes: unknown): void {
  if (!isPaperDollEnabled() || !isWfrpActor(actorValue) || isSynchronizingActor(actorValue)) {
    return;
  }

  const after = requireUpdatedSlotState(changes);

  if (!after) {
    return;
  }

  const beforeValue = actorValue.getFlag(PAPER_DOLL_MODULE_ID, PAPER_DOLL_SLOT_FLAG);

  if (beforeValue === undefined) {
    return;
  }

  if (!isPaperDollSlotState(beforeValue)) {
    throw new Error("Paper Doll's existing slot flag has an invalid shape.");
  }

  for (const change of findSlotChanges(beforeValue, after)) {
    if (!change.from) {
      continue;
    }

    const removedItem = getOwnedItem(actorValue, change.from);

    if (!removedItem) {
      continue;
    }

    if (!change.to || removedItem.type !== "armour") {
      queueUnequip(actorValue, removedItem.uuid);
    }
  }
}

function handleUpdateActor(actorValue: unknown, changes: unknown): void {
  if (!isPaperDollEnabled() || !isWfrpActor(actorValue)) {
    return;
  }

  if (!requireUpdatedSlotState(changes)) {
    return;
  }

  const itemUuids = pendingUnequips.get(actorValue.uuid);
  pendingUnequips.delete(actorValue.uuid);

  if (!itemUuids?.size) {
    return;
  }

  const items = Array.from(itemUuids, (uuid) => getOwnedItem(actorValue, uuid)).filter(
    (item): item is NonNullable<typeof item> => item !== null,
  );

  runPaperDollTask(
    Promise.all(items.map(unequipFromPaperDoll)),
    `could not unequip removed Paper Doll items for ${actorValue.uuid}`,
  );
}

function handleUpdateItem(itemValue: unknown): void {
  if (!isPaperDollEnabled() || !isWfrpOwnedItem(itemValue)) {
    return;
  }

  if (itemValue.type !== "armour" && itemValue.type !== "weapon" && !hasEquippedState(itemValue)) {
    return;
  }

  if (isWfrpActor(itemValue.parent)) {
    scheduleActorSync(itemValue.parent);
  }
}

export function registerPaperDollHooks(): void {
  registerPaperDollSlotTooltips();
  Hooks.on("paper-doll-swap", handlePaperDollSwap);
  Hooks.on("preUpdateActor", handlePreUpdateActor);
  Hooks.on("updateActor", handleUpdateActor);
  Hooks.on("updateItem", handleUpdateItem);
  Hooks.once("ready", () => {
    if (isPaperDollEnabled()) {
      try {
        enforcePaperDollSlotTypes();
        enforcePaperDollEquippedState();
      } catch (error) {
        reportPaperDollError("could not initialize the required Paper Doll integration", error);
        throw error;
      }

      runPaperDollTask(syncAllActors(), "could not synchronize all equipped items at startup");
    }
  });
}
